SELECT p.*, m.AdSoyad AS Musteri, m.BabaAdi, m.Telefon, m.Adres AS MusteriAdres, m.TCKN_VKN, gp.AdSoyad AS GirisPersoneli, tp.AdSoyad AS TeslimEden, ks.KasaAdi AS TahsilatHesabi, Nz(b.Kalan,0) AS KalanBorc
FROM ((((tbl_Parti AS p LEFT JOIN tbl_Musteri AS m ON p.MusteriID=m.MusteriID) LEFT JOIN tbl_Personel AS gp ON p.GirisPersonelID=gp.PersonelID) LEFT JOIN tbl_Personel AS tp ON p.TeslimPersonelID=tp.PersonelID) LEFT JOIN tbl_Kasa AS ks ON p.TahsilatKasaID=ks.KasaID) LEFT JOIN qry_PartiBakiye AS b ON p.PartiNo=b.PartiNo;